/**
 * A layout provider for the {@link BowTieLayout}
 */
public class BowTieLayoutProvider : AbstractLayoutProvider<FcgVertex, FcgEdge, FunctionCallGraph> {

	public static readonly string NAME = "Bow Tie Layout";

	private static readonly Icon DEFAULT_ICON = new GIcon("icon.plugin.fcg.layout.bow.tie");

	/* @Override */
	public VisualGraphLayout<FcgVertex, FcgEdge> getLayout(FunctionCallGraph graph,
			TaskMonitor monitor)
    {

		BowTieLayout layout = new BowTieLayout(graph, NAME);
		initVertexLocations(graph, layout);
		return layout;
	}

	/* @Override */
	public string getLayoutName() {
		return NAME;
	}

	/* @Override */
	public Icon getActionIcon() {
		return DEFAULT_ICON;
	}
}
